/**
 * Quiz questions - 15 per difficulty. Every correct answer and explanation is hard-coded from the
 * WHO rabies fact sheet, WHO TRS 1012 (2018), India's NCDC guidelines (2019) and the ICMR survey.
 * Nothing here is generated at runtime. Do not edit without checking the source listed on the item.
 */
import type { SourceId } from './sources'

export type Difficulty = 'easy' | 'medium' | 'hard'

export interface DifficultyInfo {
  id: Difficulty
  title: string
  blurb: string
}

export const DIFFICULTIES: DifficultyInfo[] = [
  { id: 'easy', title: 'Easy', blurb: 'The basics every child should know.' },
  { id: 'medium', title: 'Medium', blurb: 'Exposure categories, schedules and numbers.' },
  { id: 'hard', title: 'Hard', blurb: 'Details from the WHO and NCDC guidelines.' },
]

export interface QuizQuestion {
  id: string
  difficulty: Difficulty
  q: string
  /** Exactly four options. */
  options: string[]
  /** Index of the correct option. */
  answer: number
  why: string
  sources: SourceId[]
}

